function agentAuthConfiguration(env = process.env) {
  const configured = env.GPDOC_AUTH0_ISSUER || env.GPDOC_AUTH0_DOMAIN || "auth.gpdoc.io";
  const issuer = (configured.startsWith("http") ? configured : "https://" + configured).replace(/\/?$/, "/");
  return {
    issuer,
    clientId: env.GPDOC_AUTH0_CLIENT_ID || "hSllIhEMtrPrLtPZpYnNf0MOQbreziL8",
    audience: env.GPDOC_AUTH0_AUDIENCE || "https://gpdoc.us.auth0.com/api/v2/",
    scope: env.GPDOC_AUTH0_SCOPE || "openid profile email offline_access",
    deviceAuthorizationEndpoint: new URL("oauth/device/code", issuer).href,
    tokenEndpoint: new URL("oauth/token", issuer).href,
    allowDevelopmentEndpoints: env.GPDOC_ALLOW_DEVELOPMENT_ENDPOINTS === "true"
  };
}

